CREATE TABLE IF NOT EXISTS mg_accounts(id TEXT PRIMARY KEY, name TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('business','personal')), opening INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mg_assets(id TEXT PRIMARY KEY, name TEXT NOT NULL, serial TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mg_records(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('sale','service','rental','payable')), title TEXT NOT NULL, contact TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', total INTEGER NOT NULL CHECK(total>0), cost INTEGER NOT NULL DEFAULT 0 CHECK(cost>=0), due TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', asset_id TEXT REFERENCES mg_assets(id), starts TEXT, ends TEXT, notes TEXT NOT NULL DEFAULT '', actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mg_lines(id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES mg_records(id), product_id TEXT NOT NULL REFERENCES products(id), variant_id TEXT REFERENCES variants(id), name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), price INTEGER NOT NULL CHECK(price>=0));
CREATE TABLE IF NOT EXISTS mg_entries(id TEXT PRIMARY KEY, request_key TEXT NOT NULL UNIQUE, account_id TEXT NOT NULL REFERENCES mg_accounts(id), to_account_id TEXT REFERENCES mg_accounts(id), kind TEXT NOT NULL CHECK(kind IN ('income','expense','transfer')), amount INTEGER NOT NULL CHECK(amount>0), category TEXT NOT NULL, description TEXT NOT NULL, day TEXT NOT NULL, record_id TEXT REFERENCES mg_records(id), actor_id TEXT NOT NULL REFERENCES users(id), void_reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS mg_entries_day ON mg_entries(day);
CREATE INDEX IF NOT EXISTS mg_records_dates ON mg_records(asset_id,starts,ends,status);
CREATE TABLE IF NOT EXISTS mg_requests(request_key TEXT PRIMARY KEY, digest TEXT NOT NULL, record_id TEXT NOT NULL REFERENCES mg_records(id));
